SELECT 
FROM care_chat_message
WHERE thread_id = #{threadId}
  AND client_msg_id = #{clientMsgId}
  AND is_deleted = 0
LIMIT 1

SELECT 
FROM care_chat_message
WHERE thread_id = #{threadId}
  AND is_deleted = 0

      AND (
          gmt_created < #{beforeAt}
          OR (gmt_created = #{beforeAt} AND id < #{beforeId})
      )

ORDER BY gmt_created DESC, id DESC
LIMIT #{limit}

SELECT 
FROM care_chat_message
WHERE thread_id = #{threadId}
  AND is_deleted = 0

      AND (
          gmt_created > #{afterAt}
          OR (gmt_created = #{afterAt} AND id > #{afterId})
      )

ORDER BY gmt_created ASC, id ASC
LIMIT #{limit}

